import{_ as r,a0 as a,w as i,s as d,ao as l,I as p,x as t,a1 as o,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何设置Ubuntu14.04 的 SSH 无密码登录 | LCTT x X-CMD","titleTemplate":false,"description":"如何设置Ubuntu14.04 的 SSH 无密码登录 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何设置Ubuntu14.04 的 SSH 无密码登录 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何设置Ubuntu14.04 的 SSH 无密码登录 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150302 How to Setup Passwordless SSH Logon to Ubuntu 14.04","title":"如何设置Ubuntu14.04 的 SSH 无密码登录","tag":"201504","desc":""},"relativePath":"201504/20150302 How to Setup Passwordless SSH Logon to Ubuntu 14.04.md","filePath":"[post].md"}'),u={name:"201504/20150302 How to Setup Passwordless SSH Logon to Ubuntu 14.04.md"};function S(h,e,g,m,b,H){const s=a("Link");return i(),d("div",null,[e[13]||(e[13]=l(`<h1 id="如何设置ubuntu14-04-的-ssh-无密码登录" tabindex="-1">如何设置Ubuntu14.04 的 SSH 无密码登录 <a class="header-anchor" href="#如何设置ubuntu14-04-的-ssh-无密码登录" aria-label="Permalink to “如何设置Ubuntu14.04 的 SSH 无密码登录”">​</a></h1><p>大家好，今天我来向大家介绍如何在 Ubuntu12.04 上设置 SSH 的无密码登录功能。仅在工作站上有正确的（公私）密钥对以供匹配时SSH服务端才会允许你登录，反之访问将不会被允许。</p><p>正常情况下，我们需要连上SSH的控制台输入用户名及其密码才行。如果两者全部正确，我们就可以访问，反之访问被服务端拒绝。不过相比而言还有一种比用密码更安全的登录方式，我们可以在登录SSH时通过加密密钥进行无密码登录。</p><p>如果你想启用这个安全的方式，我们只需简单的禁用密码登录并只允许加密密钥登录即可。使用这种方式时，客户端计算机上会产生一对私钥和公钥。接着客户端得把公钥上传到SSH服务端的authorized_key文件中去。在授予访问前，服务器及客户端电脑会校验这个密钥对。如果服务器上的公钥与客服端提交的私钥匹配则授予访问权限，否则访问被拒绝。</p><p>这是认证到SSH服务器的非常安全的一种做法，如果你想为单一的SSH用户登录实现安全登录，这也是备受推崇的方式。这里快速的过一遍如何启用无密码登录SSH的配置过程。</p><h3 id="_1-安装openssh服务端" tabindex="-1">1.安装Openssh服务端 <a class="header-anchor" href="#_1-安装openssh服务端" aria-label="Permalink to “1.安装Openssh服务端”">​</a></h3><p>首先，我们需要更新我们的本地库索引。所以如下所见，我们需要先输入“apt-get update”</p><pre><code>$ sudo apt-get update
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/updating-repo-list.png" alt="Updating Repo Index"></p><p>现在我们可以通过以下命令安装openssh-server：</p><pre><code>$ sudo apt-get install openssh-server
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/installing-openssh-server.png" alt="Installing openssh server"></p><h3 id="_2-开启openssh服务" tabindex="-1">2. 开启openssh服务 <a class="header-anchor" href="#_2-开启openssh服务" aria-label="Permalink to “2. 开启openssh服务”">​</a></h3><p>在OpenSSH已经成功安装在Ubuntu14.04操作系统上了之后，我们要启动OpenSSH的服务。以下命令让你启动/开启服务。</p><pre><code>$ sudo service ssh start
</code></pre><p>或</p><pre><code>$ sudo /etc/init.d/ssh start
</code></pre><h3 id="_3-配置密钥对" tabindex="-1">3. 配置密钥对 <a class="header-anchor" href="#_3-配置密钥对" aria-label="Permalink to “3. 配置密钥对”">​</a></h3><p>在我们安装并启动了OpenSSH服务以后。现在终于到了要我们搞定公私钥对的时候了，在终端中运行以下命令：</p><pre><code>$ ssh-keygen -t rsa
</code></pre><p>在运行完以上命令了以后，我们需要回答一系列的问题。首先选择保存密钥的路径，按回车将会选择默认路径即家目录的一个隐藏的.ssh文件夹。下一个提示是请输入口令提醒。我个人将此留空（直接回车）。之后密钥对就会创建，大功告成。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/generating-key-pair.png" alt="Generating Key Pair"></p><p>在密钥对生成以后，我们需要将<strong>客户端上的公钥复制到SSH服务端</strong>或者主机，来创建对客户端的信任关系。运行以下命令复制客户端的公钥到服务端。</p><pre><code>$ ssh-copy-id user@ip_address
</code></pre><p>在公钥上传之后，我们现在可以禁用通过密码登陆SSH的方式了。为此，我们需要通过以下命令用文本编辑器打开<strong>/etc/ssh/ssh_config</strong>。</p><pre><code>$ sudo nano /etc/ssh/sshd_config
</code></pre><p>现在，我们需要按照下图所示去掉几行注释并进行一些赋值。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/configuring-sshd_config.png" alt="Configuring sshd Config"></p><h3 id="_4-重启ssh服务" tabindex="-1">4. 重启SSH服务 <a class="header-anchor" href="#_4-重启ssh服务" aria-label="Permalink to “4. 重启SSH服务”">​</a></h3><p>最后，在我们配置完SSH服务端后，为了使改动生效我们需要重启SSH服务。在终端或控制台运行以下命令重启。</p><pre><code>$ sudo service ssh restart
</code></pre><p>或</p><pre><code>$ sudo /etc/init.d/ssh restart
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/restarting-ssh.png" alt="Restarting ssh"></p><p>现在，我们可以试试不用密码仅用密钥对的方式登录ssh服务端了。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>太好了！我们成功的配置了无密码登录SSH。使用加密密钥对进行SSH服务器认证是非常安全的一种做法，如果你想为SSH的单一用户登录实施安全的认证这也是备受推崇的方式。所以，如果你还有什么问题或建议，请在意见框中向我们反馈。很欣慰你能读完，希望你能喜欢加密的SSH安全登录 😃</p><hr>`,38)),p("p",null,[e[1]||(e[1]=t("via: ",-1)),o(s,{href:"http://linoxide.com/ubuntu-how-to/setup-passwordless-ssh-logon-ubuntu-14-04/"},{default:n(()=>[...e[0]||(e[0]=[t("http://linoxide.com/ubuntu-how-to/setup-passwordless-ssh-logon-ubuntu-14-04/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=t("作者：",-1)),o(s,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...e[2]||(e[2]=[t("Arun Pyasi",-1)])]),_:1}),e[6]||(e[6]=t(" 译者：",-1)),o(s,{href:"https://github.com/martin2011qi"},{default:n(()=>[...e[3]||(e[3]=[t("martin2011qi",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=t("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创翻译，",-1)),o(s,{href:"http://linux.cn/"},{default:n(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const _=r(u,[["render",S]]);export{x as __pageData,_ as default};
